function useReveal() {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => entries.forEach((e) => e.isIntersecting && setShown(true)),
      { threshold: 0.2 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, shown];
}

function Reveal({ children, className = "", delay = 0 }) {
  const [ref, shown] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: shown ? 1 : 0,
        transform: shown ? "translateY(0)" : "translateY(28px)",
        transition: `opacity .7s cubic-bezier(.2,.7,.2,1) ${delay}ms, transform .7s cubic-bezier(.2,.7,.2,1) ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

function Flames({ count, total = 4, color = "#FF2E2E" }) {
  return (
    <span className="inline-flex gap-1 align-middle">
      {Array.from({ length: total }).map((_, i) => (
        <svg key={i} width="16" height="16" viewBox="0 0 24 24" style={{ opacity: i < count ? 1 : 0.22 }}>
          <path
            fill={i < count ? color : "#7a6a5a"}
            d="M12 2c1 3-2 4-2 7a4 4 0 108 0c0-1.5-1-2-1-2 1 4-1 5-2 5a3 3 0 01-3-3c0-2 2-3 0-7z"
          />
        </svg>
      ))}
    </span>
  );
}

