function FaqItem({ q, a, delay }) {
  const [open, setOpen] = useState(false);
  return (
    <Reveal delay={delay}>
      <div className={`faq-item ${open ? "is-open" : ""}`}>
        <button onClick={() => setOpen((v) => !v)}>
          <span>{q}</span>
          <span className="faq-item__icon">{open ? "–" : "+"}</span>
        </button>
        <div className="faq-item__body"><p>{a}</p></div>
      </div>
    </Reveal>
  );
}

